ClipboardPage pg_pyBody = tools.findPage(".pyUI.pyBody");

int aggCnt=0;
int grpCnt=0;

java.util.TreeMap hmGroups = new java.util.TreeMap();
java.util.HashMap hmCombo = new java.util.HashMap();

ClipboardPage pg_UIFields = null;	

ClipboardProperty cpLimit = tools.getPrimaryPage().getProperty(".pyUI.pyChart.pyLimitValue");
boolean bEnableChart = tools.getPrimaryPage().getBoolean(".pyUI.pyChart.pyEnableChart");
String strLimit = "";
if (cpLimit != null)
	strLimit = cpLimit.getStringValue();
boolean bUseLimit = false;
ClipboardProperty UIFields = pg_pyBody.getProperty(".pyUIFields");
java.util.Iterator itr_fields = UIFields.iterator();
int iTemp = 0;
java.util.List list = new java.util.ArrayList();
while (itr_fields.hasNext())
{
	ClipboardProperty cp_aResult = (ClipboardProperty) itr_fields.next();
	ClipboardPage pg_aResult = cp_aResult.getPageValue();
      	pg_aResult.getProperty(".pyGroupOrder").setValue("");
	String strOrder = pg_aResult.getString(".pySortOrder");

	/* Fix for BUG-38186 to specify a Sort Order, if Sort Type is defined and not an aggregated column */
	String strFunction = pg_aResult.getString(".pyFunction");
	String strType = pg_aResult.getString(".pySortType");
	if(strFunction.equals("") && !strType.equals("") && strOrder.equals("")){   
		strOrder = "998";
	}

	Integer IntOrder;
	iTemp++;

	if(!pg_aResult.getString(".pyFunction").equals(""))
	{
		aggCnt++;
		if (!strOrder.equals(""))
		{
			IntOrder = new Integer(strOrder);
			if (!hmCombo.containsKey(IntOrder)) 
			{
			     list = new java.util.ArrayList();
			     list.add(new Integer(iTemp));
			     java.util.Collections.sort(list);
			}
			else {
			     list = (List) hmCombo.get(IntOrder);
			     list.add(new Integer(iTemp));
			     java.util.Collections.sort(list);
			}
			hmCombo.put(IntOrder, list);	
		}
	}
	else
	{
		if (strOrder.equals("")) strOrder = "999";
		IntOrder = new Integer(strOrder);
		if (!hmGroups.containsKey(IntOrder)) 
		{
			list = new java.util.ArrayList();
			list.add(new Integer(iTemp));
			java.util.Collections.sort(list);
            }
            else {
                 list = (List) hmGroups.get(IntOrder);
                 list.add(new Integer(iTemp));
                 java.util.Collections.sort(list);
            }
		hmGroups.put(IntOrder, list);
		grpCnt++;
	}

}



if(aggCnt == 0)
{
   tools.getPrimaryPage().getProperty(".pyContent.pxIsSummary").setValue(false);
}
else
{
   tools.getPrimaryPage().getProperty(".pyContent.pxIsSummary").setValue(true);
}


if (bEnableChart && (!strLimit.equals("") && !strLimit.equals("0")) && aggCnt == 1 && grpCnt == 1)
    bUseLimit = true;
java.util.SortedSet sortedset= new  java.util.TreeSet(hmGroups.keySet());
Iterator it_sorted = sortedset.iterator();


int iSortOrder = 1;

while (it_sorted.hasNext())
{
	Integer IntTemp = (Integer) it_sorted.next();
	java.util.List list_temp = (List) hmGroups.get(IntTemp);

	for(int j=0 ; j < list_temp.size() ; j++)
	{

		int iOrder = IntTemp.intValue();
		if (aggCnt == 0 && iOrder == 999)
			continue;

		Integer IntIndex = (Integer) list_temp.get(j);
		int iIndex = IntIndex.intValue();

		pg_UIFields = tools.findPage(".pyUI.pyBody.pyUIFields(" + iIndex + ")" );	
		if( pg_UIFields != null)
		{
			if(aggCnt > 0) //summary
			{
				pg_UIFields.getProperty(".pyGroupOrder").setValue(iSortOrder);

				if (iSortOrder < grpCnt) {
					pg_UIFields.getProperty(".pySortOrder").setValue(iSortOrder);
                  if(pg_UIFields.getString(".pySortType").equals("")) {
                 pg_UIFields.getProperty(".pySortType").setValue("ASC");
                  }
                }
				else
				{
					String strOrder = pg_UIFields.getString(".pySortOrder");
					if (strOrder.equals("")) strOrder = "999";
					Integer IntOrder = new Integer(strOrder);
					if (!hmCombo.containsKey(IntOrder)) 
					{
						list = new java.util.ArrayList();
						list.add(new Integer(900+iIndex));
						java.util.Collections.sort(list);
					}
					else 
					{
					     list = (List) hmCombo.get(IntOrder);
					     list.add(new Integer(900+iIndex));
					     java.util.Collections.sort(list);
					}
					hmCombo.put(IntOrder, list);	
				}
			}
			else //list
				pg_UIFields.getProperty(".pySortOrder").setValue(iSortOrder);

          iSortOrder++;

		}

	}
}




sortedset= new  java.util.TreeSet(hmCombo.keySet());
it_sorted = sortedset.iterator();
iSortOrder--;

while (it_sorted.hasNext())
{
	Integer IntTemp = (Integer) it_sorted.next();
	java.util.List list_temp = (List) hmCombo.get(IntTemp);

	for(int j=0 ; j < list_temp.size() ; j++)
	{
		Integer IntIndex = (Integer) list_temp.get(j);
		int iIndex = IntIndex.intValue();
		if (iIndex > 900) iIndex = iIndex-900;

		pg_UIFields = tools.findPage(".pyUI.pyBody.pyUIFields(" + iIndex + ")" );	
		if( pg_UIFields != null)
		{
			pg_UIFields.getProperty(".pySortOrder").setValue(iSortOrder);
          if(pg_UIFields.getString(".pySortType").equals("")) {
                 pg_UIFields.getProperty(".pySortType").setValue("ASC");
                  }
		}
		iSortOrder++;
	}
}

if (bUseLimit)
{
         java.util.Iterator itr_fields1 = UIFields.iterator();

	while (itr_fields1.hasNext())
	{
		ClipboardProperty cp_aResult = (ClipboardProperty) itr_fields1.next();
		ClipboardPage pg_aResult = cp_aResult.getPageValue();
		String strFunction = pg_aResult.getString(".pyFunction");
		if (!strFunction.equals(""))
		{
			pg_aResult.getProperty(".pySortOrder").setValue(1);
			pg_aResult.getProperty(".pySortType").setValue("DESC");
		}
		else
			pg_aResult.getProperty(".pySortOrder").setValue(2);
	}
}

ClipboardPage pg_pyBody = tools.findPage(".pyUI.pyBody");

