ClipboardPage pg_UIFields = null;	

ClipboardProperty cpLimit = tools.getPrimaryPage().getProperty(".pyUI.pyChart.pyLimitValue");
boolean bEnableChart = tools.getPrimaryPage().getBoolean(".pyUI.pyChart.pyEnableChart");
String strLimit = "";
if (cpLimit != null)
	strLimit = cpLimit.getStringValue();
